import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

const Checkout = () => {
  const navigate = useNavigate();

  const [addresses, setAddresses] = useState([
    { name: "", address: "", phone: "" }
  ]);

  const [showNewForm, setShowNewForm] = useState(false);

  const handleChange = (index, field, value) => {
    const updated = [...addresses];
    updated[index][field] = value;
    setAddresses(updated);
  };

  const addNewAddress = () => {
    setAddresses([...addresses, { name: "", address: "", phone: "" }]);
    setShowNewForm(true);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    navigate("/order-success");
  };

  return (
    <div style={container}>

      <h1 style={{ textAlign: "center" }}>Checkout</h1>

      {/* ADDRESS SECTION */}
      <div style={card}>
        <h3>Select Address</h3>

        {addresses.map((addr, index) => (
          <div key={index} style={addressBox}>
            <input
              placeholder="Full Name"
              value={addr.name}
              onChange={(e) => handleChange(index, "name", e.target.value)}
              style={input}
            />
            <input
              placeholder="Address"
              value={addr.address}
              onChange={(e) => handleChange(index, "address", e.target.value)}
              style={input}
            />
            <input
              placeholder="Phone"
              value={addr.phone}
              onChange={(e) => handleChange(index, "phone", e.target.value)}
              style={input}
            />
          </div>
        ))}

        <button onClick={addNewAddress} style={addBtn}>
          + Add New Address
        </button>
      </div>

      {/* PAYMENT SECTION */}
      <div style={card}>
        <h3>Payment Method</h3>

        <label style={radio}>
          <input type="radio" name="payment" defaultChecked /> Cash on Delivery
        </label>

        <label style={radio}>
          <input type="radio" name="payment" /> UPI
        </label>

        <label style={radio}>
          <input type="radio" name="payment" /> Card Payment
        </label>
      </div>

      {/* FIXED BUTTON */}
      <div style={bottomBar}>
        <button onClick={handleSubmit} style={checkoutBtn}>
          Place Order
        </button>
      </div>
    </div>
  );
};

/* ================= STYLES ================= */

const container = {
  padding: "20px",
  maxWidth: "600px",
  margin: "auto",
};

const card = {
  background: "#fff",
  padding: "20px",
  borderRadius: "15px",
  boxShadow: "0 8px 20px rgba(0,0,0,0.1)",
  marginBottom: "20px",
};

const addressBox = {
  marginBottom: "15px",
  padding: "10px",
  border: "1px solid #eee",
  borderRadius: "10px",
};

const input = {
  width: "100%",
  padding: "10px",
  margin: "5px 0",
  borderRadius: "8px",
  border: "1px solid #ccc",
};

const addBtn = {
  marginTop: "10px",
  padding: "8px 12px",
  border: "none",
  borderRadius: "8px",
  background: "#eee",
  cursor: "pointer",
};

const radio = {
  display: "block",
  margin: "10px 0",
};

const bottomBar = {
  position: "sticky",
  bottom: "0",
  background: "#fff",
  padding: "15px",
  boxShadow: "0 -5px 15px rgba(0,0,0,0.1)",
};

const checkoutBtn = {
  width: "100%",
  padding: "12px",
  border: "none",
  borderRadius: "25px",
  background: "#ff4f87",
  color: "white",
  fontWeight: "600",
  cursor: "pointer",
};

export default Checkout;
